              <p className="mt-3 text-[14.5px] leading-relaxed text-ink-600">{w.gemeinde.eeg.text(f(PARK.gemeinde.eeg6CtProKwh, 1))}</p>
              <p className="mt-4 font-display text-[34px] font-bold tabular-nums text-ink-900">
